def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    weak_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('budget', 0) < DAILY_SALARY * 0.8:
                weak_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 140:
                    aggressive_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    low_supply = supply <= 17
    high_supply = supply >= 22

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    if danger >= 3:
        target = max(0.92 * DAILY_SALARY, min(max_prev + 8.0, 0.95 * budget))
        if low_supply:
            target = max(target, min(budget, max_prev + 15.0))
        return float(max(1.0, min(budget, target)))

    if danger == 2:
        target = max(0.72 * DAILY_SALARY, avg_prev * 0.55 + 8.0)
        if low_supply:
            target = max(target, min(budget, max_prev * 0.72 + 6.0))
        else:
            target = min(target, 0.82 * DAILY_SALARY)
        return float(max(1.0, min(budget, target)))

    if high_supply and aggressive_count >= 2:
        target = 18.0
    elif max_prev >= 180:
        target = 22.0 if hp >= 6 else 48.0
    elif max_prev >= 130:
        target = 26.0 if hp >= 6 else 44.0
    elif max_prev > 0:
        target = min(52.0, max(24.0, avg_prev * 0.35 + 6.0))
    else:
        target = 28.0

    if weak_opp_count >= 2 and hp >= 6 and no_water_days == 0:
        target = min(target, 24.0)

    if day >= 8:
        if hp <= 5 or no_water_days >= 1:
            target = max(target, 55.0)
        else:
            target = min(target, 30.0)

    return float(max(1.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    strong_opponent_ids = ["Bob", "David"]

    highest_strong_opp_bid = 0.0
    for opp_id, opp in opponents_status.items():
        if opp['alive'] and opp_id in strong_opponent_ids:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                if prev['bid'] > highest_strong_opp_bid:
                    highest_strong_opp_bid = prev['bid']
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    overall_highest_prev_bid = 0.0
    if yesterday_bids:
        overall_highest_prev_bid = max(yesterday_bids)

    bid_amount = 0.0

    # Desperate state: Very low HP, need water immediately
    if my_status['hp'] <= 3:
        bid_amount = DAILY_SALARY * 1.5
        if overall_highest_prev_bid > 0:
            bid_amount = max(bid_amount, overall_highest_prev_bid + 20)

    # Critical state: Low to moderate HP, need to be competitive
    elif my_status['hp'] <= 6:
        bid_amount = DAILY_SALARY * 1.2
        if overall_highest_prev_bid > 0:
            bid_amount = max(bid_amount, overall_highest_prev_bid + 10)

    # Stable state: Good HP, but still need to win given tight supply
    else:
        if highest_strong_opp_bid > 0:
            if highest_strong_opp_bid >= DAILY_SALARY * 0.9:
                bid_amount = highest_strong_opp_bid + 5
            else:
                bid_amount = DAILY_SALARY * 1.0
        elif overall_highest_prev_bid > 0:
            if overall_highest_prev_bid >= DAILY_SALARY * 0.8:
                bid_amount = overall_highest_prev_bid + 2
            else:
                bid_amount = DAILY_SALARY * 0.9
        else:
            bid_amount = DAILY_SALARY * 0.95

    bid_amount = max(bid_amount, DAILY_SALARY * 0.1)

    return min(my_status['budget'], bid_amount)

